bs.shatter_cost = 17

-- Afflictions on the mob we're hitting: aff -> time it wears off. Ours are
-- noted when the swing that gave them runs; a group partner's can be added
-- with bs.mob_aff(aff) from their lines.
bs.taffs = bs.taffs or {}

function bs.mob_aff(a, secs)
  bs.taffs[a] = acs.now() + (secs or bs.aff_secs[a] or 5)
  bs.changed()
end

function bs.mob_has(a) return (bs.taffs[a] or 0) > acs.now() end

-- Does an ability do damage (for holding it on a nearly dead mob)?
function bs.rage_damages(r)
  if r.dmg ~= nil then return r.dmg end
  if r.kind then return r.kind == "dmg" or r.kind == "cond" end
  return r.cost == 14 or r.cost == 36
end

-- Choose this swing's battlerage ability, or nil.
--   * nothing on a mob under rage_low % (it's nearly dead anyway);
--   * hurt (your health under rage_defend %): a defensive affliction (stun,
--     weakness, charm, aeon, clumsiness, amnesia) or a self ability first;
--   * a conditional only when the mob has what it needs;
--   * sensitivity first when it isn't on (+33% damage), then the biggest
--     damage ability you can afford;
--   * fear is skipped unless "bs rage fear on" (a feared mob runs away);
--   * other afflictions (inhibit, recklessness...) only if listed in
--     bs.settings.rage_extra.
function bs.choose_rage(rage, hp, myhp)
  local s, now, cls = bs.settings, acs.now(), bs.class()
  if hp and hp < (s.rage_low or 0) then return end
  local best, bestscore
  for i, r in ipairs(bs.rage_list()) do
    if rage >= (r.cost or 0) and (bs._rage_cd[cls .. i] or 0) <= now then
      local kind, score = r.kind or (bs.rage_damages(r) and "dmg" or "aff"), nil
      if kind == "dmg" then
        score = 100 + (r.cost or 0)
      elseif kind == "cond" then
        for _, n in ipairs(r.needs or {}) do if bs.mob_has(n) then score = 200 end end
      elseif kind == "aff" and r.aff and not bs.mob_has(r.aff) then
        if r.aff == "fear" and not s.rage_fear then score = nil
        elseif myhp < s.rage_defend and bs.defensive_affs[r.aff] then score = 400 - bs.defensive_affs[r.aff]
        elseif r.aff == "sensitivity" and (hp or 100) > 30 then score = 300
        elseif s.rage_extra[r.aff] or r.aff == "fear" then score = 50 end
      elseif kind == "self" and myhp < s.rage_defend then
        score = 350
      end
      if score and (not bestscore or score > bestscore) then best, bestscore = i, score end
    end
  end
  if best then return best, bs.rage_list()[best] end
end

